<input required name="name" value="<?php echo e(old('name',$type->name)); ?>" class="rounded-xl border-slate-300" placeholder="Type name"><input name="slug" value="<?php echo e(old('slug',$type->slug)); ?>" class="rounded-xl border-slate-300" placeholder="stable-slug"><select required name="area" class="rounded-xl border-slate-300"><?php $__currentLoopData = $areas; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $value=>$label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($value); ?>" <?php if(old('area',$type->area ?: 'academics_research')===$value): echo 'selected'; endif; ?>><?php echo e($label); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><input required type="number" min="0" max="10000" name="sort_order" value="<?php echo e(old('sort_order',$type->sort_order ?? 0)); ?>" class="rounded-xl border-slate-300" placeholder="Order"><textarea name="description" rows="2" maxlength="2000" class="rounded-xl border-slate-300 sm:col-span-2" placeholder="Description"><?php echo e(old('description',$type->description)); ?></textarea><?php $__currentLoopData = ['is_active'=>'Active','is_academic'=>'Academic metadata','supports_series'=>'Supports series']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $field=>$label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><label class="flex gap-2 text-sm"><input type="checkbox" name="<?php echo e($field); ?>" value="1" <?php if(old($field,$type->{$field} ?? ($field==='is_active'))): echo 'checked'; endif; ?> class="rounded"><?php echo e($label); ?></label><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?>
